Action.Str:
var raw = global("FINPEND"), pend = {};
try { if (raw && raw.charAt(0) !== "%") pend = JSON.parse(raw); } catch (e) {}
var titulo = "";
for (var i = 1; i <= 5; i++) { var v = local("evtprm" + i); if (v && pend[v]) { titulo = v; break; } }
if (titulo) { var p = pend[titulo]; setLocal("titulo", titulo); setLocal("tipo", p.tipo);
  setLocal("valor", p.valor); setLocal("estab", p.estab);
  setLocal("parcelas", p.parcelas); setLocal("ts", String(p.ts)); }
setLocal("achou", titulo ? "sim" : "nao");

setLocal("body", JSON.stringify({
  tipo: local("tipo"), valor: local("valor"), estab: local("estab"),
  parcelas: local("parcelas"), nome: local("nome"),
  categ: local("categ"), ts: local("ts")
}));

var raw = global("FINPEND"), pend = {};
try { if (raw && raw.charAt(0) !== "%") pend = JSON.parse(raw); } catch (e) {}
delete pend[local("titulo")]; setGlobal("FINPEND", JSON.stringify(pend));
